            new_width = int(target_height * aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_x = (new_width - target_width) // 2
            return resized_frame[:, crop_x:crop_x + target_width]
    return clip.fl_image(process_frame)

def resize_and_crop_horizontal(clip):
    target_width = 1920
    target_height = 1080
    def process_frame(frame):
        frame_height, frame_width = frame.shape[:2]
        aspect_ratio = frame_width / frame_height
        target_aspect_ratio = target_width / target_height
        if aspect_ratio > target_aspect_ratio:
            new_height = target_height
            new_width = int(target_height * aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_x = (new_width - target_width) // 2
            return resized_frame[:, crop_x:crop_x + target_width]
        else:
            new_width = target_width
            new_height = int(target_width / aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_y = (new_height - target_height) // 2
            return resized_frame[crop_y:crop_y + target_height, :]
    return clip.fl_image(process_frame)

def cut_video(video_path, segments, vertical_format=True, title=""):
    print("Iniciando o Corte de Vídeo…")
    video = VideoFileClip(video_path)
    for i, segment in enumerate(segments):
        start = segment['start']
        end = segment['end']
        cut = video.subclip(start, end)

        if vertical_format:
            cut = resize_and_crop_vertical(cut)
        else:
            cut = resize_and_crop_horizontal(cut)

        # Aqui mantenho o título do vídeo com espaços e adiciono a numeração
        output_filename = f"{title} #{i + 1}.mp4"
        cut.write_videofile(output_filename, codec='libx264')
        print(f'Segmento {i + 1} salvo como {output_filename}')
    video.close()
